// ============================================================
// Prepare-Okta-Identity
// n8n Code node | JavaScript | Mode: Run Once for All Items
// Position: after "Merge", before "Identity - Classify HRIS vs Okta"
//
// Validates HR data and builds the canonical Okta profile.
// This node does NOT decide effective HR state (Active / Left /
// end date reached). That is decided in:
//   - "Identity - Classify HRIS vs Okta"
//   - "Offboarding - Detect Candidates"
// using the 18:00 Europe/Berlin date rule.
// ============================================================

// ---------- Configuration ----------
const DOMAIN = 'oluopeodu.com';
const CONTRACTOR_SUFFIX = '.ext';

// V6: valid Worker Type / Employment Type combinations
const VALID_EMPLOYMENT_TYPES = {
  Employee:   ['Full-time', 'Part-time', 'Probation', 'Apprentice', 'Working Student', 'Temporary'],
  Intern:     ['Intern'],
  Contractor: ['Contract']
};

// ---------- Helpers ----------
const clean = (value) =>
  (value || '')
    .toString()
    .toLowerCase()
    .replace(/ä/g, 'ae')
    .replace(/ö/g, 'oe')
    .replace(/ü/g, 'ue')
    .replace(/ß/g, 'ss')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '');

const stripCompanySuffix = (dept) =>
  (dept || '').replace(/\s+-\s+[A-Za-z0-9]+\s*$/, '').trim();

const isIsoDate = (d) => /^\d{4}-\d{2}-\d{2}$/.test(d || '');

// ---------- Reference data ----------

// Existing Okta users — used only for email/login collision detection.
const oktaUsers = $('Okta-Get-Users')
  .all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]));

const existingAddresses = new Map();

for (const u of oktaUsers) {
  const p = u.profile || {};

  for (const address of [p.login, p.email]) {
    if (address) {
      existingAddresses.set(
        address.toLowerCase(),
        p.employeeNumber || ''
      );
    }
  }
}

// Frappe HR — source of truth for sponsor validation.
const hrRecords = new Map();

for (const r of $('HRIS-Split-Employees').all()) {
  hrRecords.set(r.json.name, r.json);
}

// Addresses generated earlier in this same execution.
const claimed = new Set();

const output = [];

// ---------- Process each HR record ----------
for (const item of $input.all()) {
  const e = item.json;
  const errors = [];

  const workerType = e.custom_worker_type;
  const employmentType = e.employment_type;

  // ----- Basic validation -----
  if (!VALID_EMPLOYMENT_TYPES[workerType]) {
    errors.push('Invalid Worker Type');
  }

  if (!e.first_name || !e.last_name) {
    errors.push('Missing first or last name');
  }

  // ----- V7: Department required -----
  if (!e.department) {
    errors.push('V7: Department is required');
  }

  // ----- V1: ID prefix must match Worker Type -----
  const hasContractorPrefix = (e.name || '').startsWith('HR-CTR-');

  if (hasContractorPrefix !== (workerType === 'Contractor')) {
    errors.push('V1: ID prefix does not match Worker Type');
  }

  // ----- V6: Worker Type / Employment Type combination -----
  if (
    VALID_EMPLOYMENT_TYPES[workerType] &&
    !VALID_EMPLOYMENT_TYPES[workerType].includes(employmentType)
  ) {
    errors.push(
      `V6: Employment Type "${employmentType}" is not valid for ${workerType}`
    );
  }

  // ----- V2: Contractors require Access Sponsor -----
  if (workerType === 'Contractor' && !e.custom_access_sponsor) {
    errors.push('V2: Contractor requires Access Sponsor');
  }

  // ----- V3: Contractors require an end date -----
  const needsEndDate = workerType === 'Contractor';

  if (needsEndDate && !e.contract_end_date) {
    errors.push('V3: Contract End Date is required');
  }

  // Past end dates are NOT validated here.
  // Effective HR state (incl. 18:00 Berlin cutoff) is decided in
  // "Identity - Classify HRIS vs Okta" and "Offboarding - Detect Candidates".

  // ----- V4: Sponsor validation -----
  if (workerType === 'Contractor' && e.custom_access_sponsor) {
    const sponsorId = e.custom_access_sponsor;
    const sponsor = hrRecords.get(sponsorId);

    if (sponsorId === e.name) {
      errors.push('V4: A contractor cannot sponsor themselves');
    } else if (!sponsor) {
      errors.push(`V4: Sponsor ${sponsorId} not found in HRIS`);
    } else {
      if (sponsor.status !== 'Active') {
        errors.push(
          `V4: Sponsor ${sponsorId} is not Active in HRIS`
        );
      }

      if (sponsor.custom_worker_type !== 'Employee') {
        errors.push(
          'V4: Sponsor must have Worker Type Employee'
        );
      }

      if (
        sponsor.date_of_joining &&
        e.date_of_joining &&
        sponsor.date_of_joining > e.date_of_joining
      ) {
        errors.push(
          'V4: Sponsor starts after the contractor'
        );
      }

      // Intentionally NO sponsor end-date comparison here.
      // A sponsor may leave while the contractor is still active.
      // A separate lifecycle process will detect an inactive
      // sponsor and alert IT/HR.
    }
  }

  // ----- V5: End date cannot precede start date -----
  if (
    isIsoDate(e.date_of_joining) &&
    isIsoDate(e.contract_end_date) &&
    e.contract_end_date < e.date_of_joining
  ) {
    errors.push(
      'V5: Contract End Date cannot be before Date of Joining'
    );
  }

  // ----- Email / login -----
  // Use Frappe company_email if supplied.
  // Otherwise generate the corporate login.
  let email = (e.company_email || '').trim().toLowerCase();

  const generatedEmail = !email;

  if (generatedEmail) {
    const first = clean(e.first_name);
    const last = clean(e.last_name);

    if (!first || !last) {
      errors.push(
        'Cannot generate an email address from this name'
      );
    } else {
      const suffix =
        workerType === 'Contractor'
          ? CONTRACTOR_SUFFIX
          : '';

      email = `${first}.${last}${suffix}@${DOMAIN}`;
    }
  }

  // ----- V9: Email validation and collision detection -----
  if (email) {
    if (
      !/^[^@\s]+@[^@\s]+$/.test(email) ||
      !email.endsWith(`@${DOMAIN}`)
    ) {
      errors.push(
        `V9: Email must be a valid address on @${DOMAIN}`
      );
    }

    // Collision = STOP.
    // Never automatically create .2 / .3 variants.
    const owner = existingAddresses.get(email);

    if (owner !== undefined && owner !== e.name) {
      errors.push(
        `V9: EMAIL COLLISION: ${email} already belongs to ${
          owner || 'another Okta user'
        }`
      );
    }

    // Collision inside the same execution.
    if (claimed.has(email)) {
      errors.push(
        `V9: EMAIL COLLISION: ${email} was generated more than once in this run`
      );
    }

    claimed.add(email);
  }

  // ----------------------------------------------------------
  // Resolve Access Sponsor name for the human-readable Okta profile
  //
  // Frappe stores:  custom_access_sponsor = HR-EMP-00001
  // Okta stores:    accessSponsor = Idan Nla
  //
  // The Frappe employee ID remains the authoritative relationship.
  // ----------------------------------------------------------
  const sponsorRecord = e.custom_access_sponsor
    ? hrRecords.get(e.custom_access_sponsor)
    : null;

  const accessSponsorName = sponsorRecord
    ? `${sponsorRecord.first_name || ''} ${sponsorRecord.last_name || ''}`.trim()
    : undefined;

  // ----- Canonical Okta profile -----
  // managerId is not set yet: Frappe reports_to must first be
  // resolved to an Okta user (separate identity-resolution step).
  const profile = {
    firstName: e.first_name,
    lastName: e.last_name,
    email: email,
    login: email,
    secondEmail: e.personal_email || undefined,
    employeeNumber: e.name,
    department: stripCompanySuffix(e.department),
    title: e.designation || undefined,
    city: e.branch || undefined,
    workerType: workerType,
    employmentType: employmentType || undefined,
    accessSponsor: accessSponsorName,
    engagementEndDate: e.contract_end_date || undefined
  };

  output.push({
    json: {
      identityOk: errors.length === 0,
      errors,
      errorSummary: errors.join(' | '),
      hrId: e.name,
      generatedEmail,
      proposedEmail: email,
      workerType,
      employmentType,
      profile
    }
  });
}

return output;

// n8n Code node | JavaScript | Run Once for All Items
//
// Match key:
//   Frappe HR name <-> Okta profile.employeeNumber
//
// Actions:
//   joiner | rehire | no_change | mover | okta_only
//
// Guards:
//   invalid | conflict
//
// HR state model (see hrState()):
//   offboardingSignal = status === 'Left'
//                       OR relieving_date reached
//                       OR contractor contract_end_date reached
//                       (dates: from 18:00 Europe/Berlin on that date)
//   active            = status === 'Active' AND NOT offboardingSignal
//
// Ownership rules:
//   - Only an effectively Active HR record may become a joiner,
//     trigger a rehire, or receive mover updates.
//   - HR record with an offboarding signal: the offboarding branch
//     owns the lifecycle transition; classification does nothing.
//   - HR record neither active nor offboarding (e.g. Inactive,
//     Suspended): no automated owner; classification reports
//     "review required" and does nothing.
//
//   IMPORTANT: offboardingSignal must stay identical to the
//   triggers in "Offboarding - Detect Candidates".
// ============================================================


// ---------- Configuration ----------

// Only Okta users in our managed HR identity namespace.
const MANAGED_ID = /^HR-(EMP|CTR)-\d+$/;

// These are the canonical attributes used for mover detection.
// email, login and employeeNumber are deliberately excluded.
const COMPARED_FIELDS = [
  'firstName',
  'lastName',
  'secondEmail',
  'department',
  'title',
  'city',
  'workerType',
  'employmentType',
  'accessSponsor',
  'engagementEndDate'
];


// ---------- Date rule (keep identical to Detect Candidates) ----------

const now = $now.setZone('Europe/Berlin');
const today = now.toISODate();
const currentTime = now.toFormat('HH:mm');

const dateSignalReached = (date) => {
  if (!date) {
    return false;
  }

  return (
    date < today ||
    (date === today && currentTime >= '18:00')
  );
};


// ---------- Helpers ----------

const norm = (value) => {
  if (value === undefined || value === null) {
    return '';
  }

  return String(value).trim();
};

// Effective HR state of one HR record.
//
//   active:            true only if status Active and no offboarding signal
//   offboardingSignal: true if Detect Candidates would pick this record up
//   label:             human-readable explanation for reasons / audit
const hrState = (hris) => {

  if (!hris) {
    return {
      active: false,
      offboardingSignal: false,
      label: 'missing'
    };
  }

  const isLeft = hris.status === 'Left';

  const relievingDateReached =
    dateSignalReached(hris.relieving_date);

  const contractorEndDateReached =
    hris.custom_worker_type === 'Contractor' &&
    dateSignalReached(hris.contract_end_date);

  const offboardingSignal =
    isLeft ||
    relievingDateReached ||
    contractorEndDateReached;

  const details = [];

  if (relievingDateReached) {
    details.push(`relieving_date ${hris.relieving_date} reached`);
  }

  if (contractorEndDateReached) {
    details.push(`contract_end_date ${hris.contract_end_date} reached`);
  }

  const label = details.length
    ? `${hris.status}; ${details.join('; ')}`
    : hris.status;

  return {
    active: hris.status === 'Active' && !offboardingSignal,
    offboardingSignal,
    label
  };
};


// ---------- Reference: existing Okta users ----------

const oktaUsers = $('Okta-Get-Users')
  .all()
  .flatMap((item) =>
    Array.isArray(item.json)
      ? item.json
      : [item.json]
  );

const oktaByHrId = new Map();
const duplicateIds = new Set();

for (const user of oktaUsers) {

  const profile = user.profile || {};
  const hrId = profile.employeeNumber;

  // Ignore Okta admins, service accounts, etc.
  if (!hrId || !MANAGED_ID.test(hrId)) {
    continue;
  }

  if (oktaByHrId.has(hrId)) {
    duplicateIds.add(hrId);
  }

  oktaByHrId.set(hrId, user);
}


// ---------- Reference: all Frappe HR records ----------

const hrById = new Map();

for (const item of $('HRIS-Split-Employees').all()) {

  hrById.set(
    item.json.name,
    item.json
  );
}


// ---------- Track HRIS identities processed ----------

const processed = new Set();

const output = [];


// ============================================================
// CLASSIFY HRIS IDENTITIES
// (all HR records arrive here; effective HR state decides
//  which actions are allowed)
// ============================================================

for (const item of $input.all()) {

  const prepared = item.json;
  const hrId = prepared.hrId;

  processed.add(hrId);

  // Authoritative HR record (source of truth).
  const hris = hrById.get(hrId);
  const state = hrState(hris);

  const result = {
    hrId,
    action: null,
    reason: '',
    oktaUserId: null,
    oktaStatus: null,

    changes: [],
    changeCount: 0,
    changeSummary: '',

    updatePayload: null,

    errorSummary: prepared.errorSummary || '',

    profile: prepared.profile
  };


  // ----------------------------------------------------------
  // Validation failed during identity preparation
  // ----------------------------------------------------------

  if (!prepared.identityOk) {

    result.action = 'invalid';
    result.reason = 'Failed identity validation';

    output.push({
      json: result
    });

    continue;
  }


  // ----------------------------------------------------------
  // Find existing Okta identity
  // ----------------------------------------------------------

  const match = oktaByHrId.get(hrId);


  // Duplicate employeeNumber in Okta
  // requires human investigation.
  if (duplicateIds.has(hrId)) {

    result.action = 'conflict';

    result.reason =
      'More than one Okta user has this employeeNumber';

    output.push({
      json: result
    });

    continue;
  }


  // ----------------------------------------------------------
  // No Okta identity and HR record is not effectively Active
  //
  // Never create an account for a Left, inactive, missing,
  // or date-expired HR record.
  // ----------------------------------------------------------

  if (!match && !state.active) {

    result.action = 'no_change';

    result.reason =
      `No Okta identity and HRIS state is "${state.label}"; account creation skipped`;

    output.push({
      json: result
    });

    continue;
  }


  // ----------------------------------------------------------
  // No Okta identity and HR record is effectively Active → JOINER
  // ----------------------------------------------------------

  if (!match) {

    result.action = 'joiner';
    result.reason = 'Active HRIS identity does not exist in Okta';

    output.push({
      json: result
    });

    continue;
  }


  // ----------------------------------------------------------
  // Existing Okta identity
  // ----------------------------------------------------------

  result.oktaUserId = match.id;
  result.oktaStatus = match.status;


  // ----------------------------------------------------------
  // DEPROVISIONED Okta identity
  //
  // Reactivate only if the HR record is effectively Active:
  // status Active AND no end date reached.
  // A stale "Active" next to a past end date is NOT a rehire.
  // ----------------------------------------------------------

  if (match.status === 'DEPROVISIONED') {

    if (!state.active) {

      result.action = 'no_change';

      result.reason =
        `Okta account is DEPROVISIONED and HRIS state is "${state.label}"; reactivation skipped`;

      output.push({
        json: result
      });

      continue;
    }

    // HR says the person is working again
    // (e.g. end date extended, or relieving date cleared).
    result.action = 'rehire';

    result.reason =
      'Effectively Active HRIS identity matches a DEPROVISIONED Okta account';

    output.push({
      json: result
    });

    continue;
  }


  // ----------------------------------------------------------
  // Existing Okta identity, HR record NOT effectively Active
  //
  // Classification never updates such an identity.
  //   - offboarding signal present → offboarding branch owns it
  //   - no offboarding signal (e.g. Inactive, Suspended)
  //     → no automated owner, human review required
  // ----------------------------------------------------------

  if (!state.active) {

    result.action = 'no_change';

    result.reason = state.offboardingSignal
      ? `Okta account is ${match.status} and HRIS state is "${state.label}"; lifecycle update skipped because offboarding owns this identity`
      : `Okta account is ${match.status} and HRIS state is "${state.label}"; no automated lifecycle owner, review required`;

    output.push({
      json: result
    });

    continue;
  }


  // ----------------------------------------------------------
  // Compare canonical HRIS profile against Okta profile
  // (only effectively Active HR records reach this point)
  // ----------------------------------------------------------

  const oktaProfile = match.profile || {};

  const updateProfile = {};


  for (const field of COMPARED_FIELDS) {

    const from = norm(oktaProfile[field]);
    const to = norm(prepared.profile[field]);

    if (from !== to) {

      result.changes.push({
        field,
        from,
        to
      });

      updateProfile[field] =
        to === ''
          ? null
          : to;
    }
  }


  // ----------------------------------------------------------
  // Determine action explicitly from change count
  // ----------------------------------------------------------

  result.changeCount = result.changes.length;


  if (result.changeCount === 0) {

    result.action = 'no_change';

    result.reason =
      'Canonical HRIS and Okta profiles match';

  } else {

    result.action = 'mover';

    result.reason =
      'One or more managed profile attributes changed';

    result.changeSummary =
      result.changes
        .map(
          (change) =>
            `${change.field}: "${change.from}" -> "${change.to}"`
        )
        .join(' | ');

    result.updatePayload = {
      profile: updateProfile
    };
  }


  output.push({
    json: result
  });
}


// ============================================================
// OKTA-ONLY IDENTITIES
//
// Managed Okta identities that did not appear in the HRIS input.
//
// They may represent:
//   - an employee who became inactive / Left
//   - an orphaned Okta account
//
// The reason explains which case applies.
// ============================================================

for (const [hrId, user] of oktaByHrId) {

  // Already processed as an HRIS identity.
  if (processed.has(hrId)) {
    continue;
  }


  // Already fully deprovisioned: no action required.
  if (user.status === 'DEPROVISIONED') {
    continue;
  }


  const hris = hrById.get(hrId);

  let reason;

  if (hris) {

    reason =
      `HRIS status is ${hris.status}, Okta account is still ${user.status}`;

  } else {

    reason =
      'No matching HRIS record (orphan)';
  }


  output.push({
    json: {
      hrId,

      action: 'okta_only',

      reason,

      oktaUserId: user.id,

      oktaStatus: user.status,

      changes: [],

      changeCount: 0,

      changeSummary: '',

      updatePayload: null,

      errorSummary: '',

      profile: user.profile || {}
    }
  });
}


// ============================================================
// RETURN CLASSIFIED IDENTITIES
// ============================================================

return output;

// Offboarding - Detect Candidates
// Input: ALL employees from HRIS-Split-Employees
// Output: only employees who are offboarding candidates
//
// Eligibility policy:
// Any single HR offboarding signal is enough:
// - status === "Left" -> eligible immediately
// - relieving_date -> eligible from 18:00 Berlin on that date
// - contractor contract_end_date -> eligible from 18:00 Berlin on that date
//
// Date policy:
// relieving_date and contract_end_date represent the final working/access day.
// Therefore, date-based offboarding becomes eligible at 18:00 Berlin on that date.
// If the scheduled 18:00 run is missed, a later run catches up.
//
// Schedule policy:
// Weekdays: hourly from 08:00 through 18:00
// Weekends: 18:00 catch-up run

const now = $now.setZone('Europe/Berlin');
const today = now.toISODate();
const currentTime = now.toFormat('HH:mm');

const dateSignalReached = (date) => {
  if (!date) {
    return false;
  }

  return (
    date < today ||
    (date === today && currentTime >= '18:00')
  );
};

return items
  .filter(item => {
    const emp = item.json;

    const isLeft = emp.status === 'Left';

    const relievingDateReached =
      dateSignalReached(emp.relieving_date);

    const contractorEndDateReached =
      emp.custom_worker_type === 'Contractor' &&
      dateSignalReached(emp.contract_end_date);

    return (
      isLeft ||
      relievingDateReached ||
      contractorEndDateReached
    );
  })
  .map(item => {
    const emp = item.json;

    const isLeft = emp.status === 'Left';

    const relievingDateReached =
      dateSignalReached(emp.relieving_date);

    const contractorEndDateReached =
      emp.custom_worker_type === 'Contractor' &&
      dateSignalReached(emp.contract_end_date);

    let offboarding_trigger;

    if (isLeft && relievingDateReached) {
      offboarding_trigger = 'left_and_relieving_date_reached';
    } else if (isLeft) {
      offboarding_trigger = 'status_left';
    } else if (contractorEndDateReached) {
      offboarding_trigger = 'contract_end_date_reached';
    } else {
      offboarding_trigger = 'relieving_date_reached';
    }

    return {
      json: {
        ...emp,
        offboarding_trigger,
        deactivation_eligible: true,
        offboarding_detected_on: today,
      },
    };
  });

// Offboarding - Match Okta User
//
// Input: candidates from Offboarding - Detect Candidates
// Reference: Okta-Get-Users from the same execution
// Match key: Frappe employee name <-> Okta profile.employeeNumber
//
// Guard:
// Okta-Get-Users has "Always Output Data" enabled. If Okta returns
// no users (e.g. missing permissions returning [] with HTTP 200),
// the node emits one EMPTY item instead of zero items.
// Without this guard, every candidate would silently become
// "no_identity_to_deactivate" and leavers would keep their access.
// Only real Okta users (items with an id) are counted.

const candidates = items;

const oktaUsers = $('Okta-Get-Users')
  .all()
  .filter(oktaItem => oktaItem.json?.id);

if (oktaUsers.length === 0) {
  throw new Error(
    'Okta-Get-Users returned no HR users; refusing to evaluate offboarding'
  );
}

return candidates.map(item => {
  const employee = item.json;
  const employeeNumber = employee.name;

  const matches = oktaUsers.filter(oktaItem =>
    oktaItem.json?.profile?.employeeNumber === employeeNumber
  );

  let match_status;

  if (matches.length === 0) {
    match_status = 'no_identity_to_deactivate';
  } else if (matches.length > 1) {
    match_status = 'duplicate_identity';
  } else {
    match_status = 'matched';
  }

  return {
    json: {
      ...employee,
      match_status,
      match_count: matches.length,

      ...(matches.length === 1
        ? {
            okta_user_id: matches[0].json.id,
            okta_user_status: matches[0].json.status,
            okta_user: matches[0].json,
          }
        : {}),
    },
  };
});

