// Offboarding - Leaver Circuit Breaker
//
// Position: Check Okta Status (eligible) -> here -> OKTA-Deactivate-User
//
// Counts only identities about to be deactivated in THIS run.
// Historical leavers (already DEPROVISIONED) never reach this node.
//
// Policy:
// - 1–2 eligible deactivations -> continue
// - >2                         -> fail closed (error-handler alerts #it-alerts)
//
// Threshold is intentionally conservative for this 7-person lab.
// Reference points: Okta import safeguard default 20%,
// Microsoft Entra accidental-deletion default 500 per sync cycle.

const MAX_DEACTIVATIONS_PER_RUN = 2;

const count = items.length;

if (count > MAX_DEACTIVATIONS_PER_RUN) {
  throw new Error(
    `OFFBOARDING CIRCUIT BREAKER: ${count} deactivations pending; maximum allowed is ${MAX_DEACTIVATIONS_PER_RUN}`
  );
}

return items;

parameters.text:
=🧪 DRY RUN – would deactivate
Employee: {{ $json.name }} – {{ $json.first_name }} {{ $json.last_name }}
Trigger: {{ $json.offboarding_trigger }}
Okta status: {{ $json.okta_user_status }}

=⚠️ Offboarding needs review – no action taken     
Employee: {{ $json.name }} – {{ $json.first_name }} {{ $json.last_name }}     
Trigger: {{ $json.offboarding_trigger }}     
Okta status: {{ $json.okta_user_status || 'missing' }}     
Reason: {{ $json.okta_user_status === 'SUSPENDED' ? 'Okta account is SUSPENDED; deactivation needs a human decision' : 'Unexpected Okta status; automation did not act' }}

=⚠️ Duplicate Okta identity – no action taken
Employee: {{ $json.name }} – {{ $json.first_name }} {{ $json.last_name }}
